class Relic {
  constructor(name, rarity) {
    this.name = name;
    this.rarity = rarity;
  }

  examine() {
    return `This is a ${this.rarity} relic called ${this.name}.`;
  }

  displayRarity() {
    return `Rarity: ${this.rarity}`;
  }
}

class MagicalOrb extends Relic {
  constructor(name, rarity, magicType) {
    super(name, rarity);
    this.magicType = magicType;
  }

  examine() {
    return `${super.examine()} It pulses with ${this.magicType} energy.`;
  }

  castSpell() {
    return `The ${this.name} unleashes a potent ${this.magicType} spell!`;
  }
}

// Test cases (for verification)
const ancientOrb = new MagicalOrb("Orb of Eldoria", "Legendary", "Arcane");
console.log(ancientOrb.examine());
console.log(ancientOrb.displayRarity());
console.log(ancientOrb.castSpell());

const fierySphere = new MagicalOrb("Sphere of Cinder", "Rare", "Fire");
console.log(fierySphere.examine());
console.log(fierySphere.castSpell());

